import{_ as e,o as r,c as a,a6 as d}from"./chunks/framework.BJFjZBwW.js";const o="/dev/assets/OpenMQTTgateway_ESP32_Addon_RF.AiTlN2pd.png",n="/dev/assets/OpenMQTTgateway_ESP8266_Addon_RF.EIugcvvu.png",y=JSON.parse('{"title":"RF gateway (433/315/868/915MHz)","description":"","frontmatter":{},"headers":[],"relativePath":"setitup/rf.md","filePath":"setitup/rf.md","lastUpdated":1785770623000}'),i={name:"setitup/rf.md"};function s(l,t,c,h,u,p){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="rf-gateway-433-315-868-915mhz" tabindex="-1">RF gateway (433/315/868/915MHz) <a class="header-anchor" href="#rf-gateway-433-315-868-915mhz" aria-label="Permalink to &quot;RF gateway (433/315/868/915MHz)&quot;">​</a></h1><h2 id="protocols-modules-and-library" tabindex="-1">Protocols, modules and library <a class="header-anchor" href="#protocols-modules-and-library" aria-label="Permalink to &quot;Protocols, modules and library&quot;">​</a></h2><p>RTL_433 covers OOK protocols detailed <a href="./../use/rf.html#supported-decoders">here</a> and supports auto-discovery following Home Assistant convention. The other libraries/modules are more for advanced users.</p><table tabindex="0"><thead><tr><th>Board</th><th style="text-align:center;">Protocols</th><th style="text-align:center;">Assembly/Soldering required</th></tr></thead><tbody><tr><td>Heltec LORA V2 433Mhz</td><td style="text-align:center;"><a href="./../use/rf.html#supported-decoders">RTL_433</a>, receiving only</td><td style="text-align:center;">No</td></tr><tr><td>LILYGO® LoRa32 V2.1_1.6.1 433 Mhz</td><td style="text-align:center;"><a href="./../use/rf.html#supported-decoders">RTL_433</a>, receiving only</td><td style="text-align:center;">No</td></tr><tr><td>ESP32 + SX127X</td><td style="text-align:center;"><a href="./../use/rf.html#supported-decoders">RTL_433</a>, receiving only</td><td style="text-align:center;">Yes</td></tr><tr><td>ESP32 + CC1101</td><td style="text-align:center;"><a href="./../use/rf.html#supported-decoders">RTL_433</a>, RF(RCSwitch), RF2(KaKu), Pilight</td><td style="text-align:center;">Yes</td></tr><tr><td>ESP8266 + Basic RF modules (SRX, STX, XD RF, FS1000A</td><td style="text-align:center;">RF(RCSwitch), RF2(KaKu), Pilight</td><td style="text-align:center;">Yes</td></tr><tr><td>ESP8266 + CC1101 (might have lower range than with SRX/STX above)</td><td style="text-align:center;">RF(RCSwitch), RF2(KaKu), Pilight</td><td style="text-align:center;">Yes</td></tr><tr><td>ESP32 + Basic RF modules (SRX, STX, XD RF, FS1000A</td><td style="text-align:center;">RF(RCSwitch), RF2(KaKu), Pilight</td><td style="text-align:center;">Yes</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you want to try the RTL_433 module with a combination or a board outside of this list, verify that it has an SX1278 or a SX1276</p></div><p>Heltec LORA V3 is not compatible with RTL_433 library as it is based on an SX1262 module.</p><h2 id="assembly-soldering-required-parts" tabindex="-1">Assembly/soldering required parts <a class="header-anchor" href="#assembly-soldering-required-parts" aria-label="Permalink to &quot;Assembly/soldering required parts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Purpose</th><th>Compatible modules</th><th>Receiver Switching</th></tr></thead><tbody><tr><td>SRX882 or SRX882S (recommended)</td><td>433Mhz Receiver</td><td>RF(RCSwitch), RF2(KaKu), Pilight</td><td>Supported</td></tr><tr><td>STX882 (recommended)</td><td>433Mhz Transmitter</td><td>RF(RCSwitch), RF2(KaKu), Pilight</td><td>Supported</td></tr><tr><td>CC1101</td><td>433Mhz Transceiver</td><td><a href="./../use/rf.html#supported-decoders">RTL_433</a>, RF(RCSwitch), RF2(KaKu), Pilight</td><td>Supported</td></tr><tr><td>SX1276/SX1278</td><td>433Mhz Transceiver</td><td><a href="./../use/rf.html#supported-decoders">RTL_433</a></td><td>Not Supported</td></tr><tr><td>LilyGo/Heltec</td><td>433Mhz Transceiver</td><td><a href="./../use/rf.html#supported-decoders">RTL_433</a></td><td>Not Supported</td></tr></tbody></table><h3 id="srx-stx-pinout" tabindex="-1">SRX STX Pinout <a class="header-anchor" href="#srx-stx-pinout" aria-label="Permalink to &quot;SRX STX Pinout&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Board</th><th style="text-align:center;">Receiver Pin</th><th style="text-align:center;">Emitter Pin</th></tr></thead><tbody><tr><td>ESP8266</td><td style="text-align:center;"><strong>D2</strong>/D1/D8</td><td style="text-align:center;"><strong>RX</strong>/D2</td></tr><tr><td>ESP32</td><td style="text-align:center;"><strong>27</strong>/26</td><td style="text-align:center;">12</td></tr><tr><td>RF BRIDGE</td><td style="text-align:center;">-</td><td style="text-align:center;">-</td></tr><tr><td>RF BRIDGE <a href="https://github.com/xoseperez/espurna/wiki/Hardware-Itead-Sonoff-RF-Bridge---Direct-Hack" target="_blank" rel="noreferrer">DIRECT HACK</a></td><td style="text-align:center;">4</td><td style="text-align:center;">5</td></tr><tr><td>SONOFF RFR3</td><td style="text-align:center;">4</td><td style="text-align:center;">-</td></tr><tr><td>RF WIFI GATEWAY</td><td style="text-align:center;">5</td><td style="text-align:center;">-</td></tr></tbody></table><p>Connect the Emitter and Receiver to a 5V or 3.3V supply source, check datasheet of your modules to confirm (<strong>3.3V</strong> for CC1101), and the ground of your supply source to the ground of your board.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>With SRX882S receiver connect the CS pin to 3.3V</p></div><h3 id="cc1101-pinout" tabindex="-1">CC1101 Pinout <a class="header-anchor" href="#cc1101-pinout" aria-label="Permalink to &quot;CC1101 Pinout&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Board</th><th style="text-align:center;">Receiver Pin(GDO2)</th><th style="text-align:center;">Emitter Pin(GDO0)</th><th style="text-align:center;">SCK</th><th style="text-align:center;">VCC</th><th style="text-align:center;">MOSI</th><th style="text-align:center;">MISO</th><th style="text-align:center;">CSN</th><th style="text-align:center;">GND</th></tr></thead><tbody><tr><td>ESP8266</td><td style="text-align:center;"><strong>D2</strong>/D1/D8</td><td style="text-align:center;"><strong>RX</strong>/D2</td><td style="text-align:center;">D5</td><td style="text-align:center;"><strong>3V3</strong></td><td style="text-align:center;">D7</td><td style="text-align:center;">D6</td><td style="text-align:center;">D8</td><td style="text-align:center;">GND</td></tr><tr><td>ESP32</td><td style="text-align:center;"><strong>D27</strong></td><td style="text-align:center;">D12</td><td style="text-align:center;">D18</td><td style="text-align:center;"><strong>3V3</strong></td><td style="text-align:center;">D23</td><td style="text-align:center;">D19</td><td style="text-align:center;">D5</td><td style="text-align:center;">GND</td></tr></tbody></table><p>To use the CC1101 module, <code>ZradioCC1101</code> must be uncomment in the <code>User_config.h</code> or added to the <code>build_flags</code>.</p><p>More information about the <a href="https://github.com/LSatan/SmartRC-CC1101-Driver-Lib#wiring" target="_blank" rel="noreferrer">CC1101 wiring</a>.</p><div class="tip custom-block"><p class="custom-block-title">Please note that with OMG we are recommending CC1101 GDO2 to be connected to ESP32 D27 and GDO0 to be connected to D12, this is different than the LSatan diagram. This is due to the ESP32 using D2 as part of the boot process.</p><p>If you want to use custom SPI pins for the CC1101 module, you can define the following variables in your <code>User_config.h</code> or as <code>build_flags</code> in <code>platformio.ini</code>:</p><ul><li><code>RF_CC1101_SCK</code>: SPI clock pin (SCK)</li><li><code>RF_CC1101_SCK</code>: SPI clock pin (SCK)</li><li><code>RF_CC1101_MISO</code>: SPI MISO pin (Master In Slave Out)</li><li><code>RF_CC1101_MOSI</code>: SPI MOSI pin (Master Out Slave In)</li><li><code>RF_CC1101_CS</code>: SPI chip select pin (CSN)</li></ul><p>When <strong>all</strong> these variables are defined, OpenMQTTGateway will use your custom pinout for the CC1101 connection. This is useful if your board does not use the default pins or if you want to avoid conflicts with other devices.</p></div><h2 id="esp32-hardware-setup" tabindex="-1">ESP32 Hardware setup <a class="header-anchor" href="#esp32-hardware-setup" aria-label="Permalink to &quot;ESP32 Hardware setup&quot;">​</a></h2><p><img src="'+o+'" alt="Addon_RF"></p><h2 id="esp8266-hardware-setup" tabindex="-1">ESP8266 Hardware setup <a class="header-anchor" href="#esp8266-hardware-setup" aria-label="Permalink to &quot;ESP8266 Hardware setup&quot;">​</a></h2><p>If the gateway works only when serial monitor is connected don&#39;t use D3 use D2 instead (gpio 4) and modify config_RF.h accordingly.</p><p>With SRX882 some users reported that D3 is not working use D1 instead in this case and modify config_RF.h accordingly.</p><p><img src="'+n+'" alt="Addon_RF"></p><h2 id="sonoff-rf-bridge-hardware-setup" tabindex="-1">SONOFF RF Bridge Hardware setup <a class="header-anchor" href="#sonoff-rf-bridge-hardware-setup" aria-label="Permalink to &quot;SONOFF RF Bridge Hardware setup&quot;">​</a></h2><p>Per default there is no need on modifying the RF Bridge hardware, unless you don&#39;t want to use the provided RF controller (EFM8BB1). Indeed if you want to extend the protocols supported by the bridge you can <a href="https://github.com/xoseperez/espurna/wiki/Hardware-Itead-Sonoff-RF-Bridge---Direct-Hack" target="_blank" rel="noreferrer">bypass this controller</a> and use the ESP8255 capacities to decode RF Signal. The RF processing can be achieved after the modification by either RF, RF2 or Pilight gateways.</p><h2 id="sonoff-rfr3-hardware-setup" tabindex="-1">SONOFF RFR3 Hardware setup <a class="header-anchor" href="#sonoff-rfr3-hardware-setup" aria-label="Permalink to &quot;SONOFF RFR3 Hardware setup&quot;">​</a></h2><p><a href="https://1technophile.blogspot.com/2019/08/new-sonoff-rfr3-as-433tomqtt-gateway.html" target="_blank" rel="noreferrer">Connect GPIO4 of the ESP8255 to the pin D0 of SYN470</a></p><h2 id="wifi-rf-gateway-hardware-setup" tabindex="-1">WIFI RF GATEWAY Hardware setup <a class="header-anchor" href="#wifi-rf-gateway-hardware-setup" aria-label="Permalink to &quot;WIFI RF GATEWAY Hardware setup&quot;">​</a></h2><p>This board doesn&#39;t require any hardware modifications.</p>',29)])])}const f=e(i,[["render",s]]);export{y as __pageData,f as default};
